  "recovered_c": "uint64_t custom_hash(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  uint64_t uVar1;\n  size_t out_cap_local;\n  uint8_t *out_local;\n  uint64_t arg_local;\n  size_t len_local;\n  uint8_t *in_local;\n  uint32_t s;\n  uint r;\n  uint32_t k0;\n  uint32_t k1;\n  uint32_t k2;\n  uint32_t k3;\n\n  s = 0;\n  if ((len < 0x18) || (out_cap < 8)) {\n    uVar1 = 0xffffffffffffffff;\n  } else {\n    uint32_t v0 = *(uint32_t *)in;\n    uint32_t v1 = *(uint32_t *)(in + 4);\n    for (r = 0; r < 0x20; r++) {\n      s = s + 0x9e3779b9;\n      v0 = v0 + (*(int *)(in + 0xc) + (v1 >> 5) ^ v1 * 0x10 + *(int *)(in + 8) ^ s + v1);\n      v1 = v1 + (*(int *)(in + 0x14) + (v0 >> 5) ^ v0 * 0x10 + *(int *)(in + 0x10) ^ s + v0);\n    }\n    *out = (uint8_t)v0;\n    out[1] = (uint8_t)(v0 >> 8);\n    out[2] = (uint8_t)(v0 >> 0x10);\n    out[3] = (uint8_t)(v0 >> 0x18);\n    out[4] = (uint8_t)v1;\n    out[5] = (uint8_t)(v1 >> 8);\n    out[6] = (uint8_t)(v1 >> 0x10);\n    out[7] = (uint8_t)(v1 >> 0x18);\n    uVar1 = 8;\n  }\n  return uVar1;\n}"
